@if($items->hasPages())<nav class="pagination" aria-label="Paginação"><span>{{$items->firstItem()}}–{{$items->lastItem()}} de {{$items->total()}} registros</span><div class="actions">@if($items->onFirstPage())<span class="muted">Anterior</span>@else<a class="button button-secondary small-button" href="{{$items->previousPageUrl()}}">Anterior</a>@endif<span>Página {{$items->currentPage()}} de {{$items->lastPage()}}</span>@if($items->hasMorePages())<a class="button button-secondary small-button" href="{{$items->nextPageUrl()}}">Próxima</a>@else<span class="muted">Próxima</span>@endif</div></nav>@elseif(method_exists($items,'total')&&$items->total())<p class="muted pagination">{{$items->total()}} registros</p>@endif